class MismatchingValue(Exception):
    """
    Raised when values in specific key in one of two compared
    dictionaries in compare_two_dicts method does not match.
    """
    pass


class ParameterDoesNotExist(Exception):
    """
    Raised when requested parameter in Partial Test Results or
    Cumulative Test Results in validate_cumulative_results method
    from sign_analyzer.py does not exist.
    """
    pass


class TestModuleStartingFailure(Exception):
    """
    Raised when test module could not start due to BTS request rejection.
    """
    pass


class MismatchingKeysException(Exception):
    """
    Raised when there exists any key in one of two dicts
    that does not exist in other dictionary passed as
    arguments to compare_two_dicts method.
    """
    pass


class DifferenceInResults(Exception):
    """
    Raised when summed up partial results from Partial Results Table
    are not equal the value from Cumulative Results Table for requested
    param name in validate_cumulative_results method in sign_analyzer.py.
    """
    pass


class RSSIDiffAboveThreshold(Exception):
    """
    Raised when RSSI Parameter in some measure in Partial Results Table in 5G Uplink
    test models is higher than absolute value of 5 in reference to randomly chosen RSSI
    value from this table.
    """
    pass


class NoMatchingAckBitsValue(Exception):
    """
    Raised when there is unknown ack bits value for test type and pucch symbol provided to test.
    """
    pass


class DuplicatedRssiValue(Exception):
    """
    Raised when there are duplicated RSSI values in partial results table.
    """
    pass


class NoMatchingMethodForValidatingCounters(Exception):
    """
    Raised when there is not known way for validating counters for given pucch symbol and test format provided.
    """
    pass


class CellNotFound(Exception):
    """
    Raised when provided cell is not in current configuration.
    """
    pass


class IncorrectTestModelParameter(Exception):
    """
    Raised when provided test model's parameter is incorrect.
    """
    pass


class RuntimeDistnameNotFound(Exception):
    """
    Raised when runtime configuration distname cannot be found for cell
    """


class UnsupportedTestType(Exception):
    """
    Raised when provided test type is not supported
    """


class VswrTimeShiftResultsError(Exception):
    """
    Raised when Time Shift of WebUI VSWR results is not correct.
    """


class VswrMeasurementCountNotCorrect(Exception):
    """
    Raised when the number of VSWR measurement is not correct.
    """


class VswrValueNotCorrect(Exception):
    """
    Raised when the value of VSWR measurement is not correct.
    """


class ReportingTimeIntervalError(Exception):
    """
    Raised when the reporting time intervals are not correct.
    """
    pass


class SumOfParametersNotConstant(Exception):
    """
    Raised when the sum of parameters is not constant in every measure.
    """
    pass


class ValuesNotEqualError(Exception):
    """
    Raised when the value is not equal to the number of uplink slots in the measurement interval.
    """
    pass
